"use strict";
const $=id=>document.getElementById(id);
const el=(tag,text,cls)=>{const n=document.createElement(tag);if(text!==undefined)n.textContent=text;if(cls)n.className=cls;return n;};
const guide=[["abstract","A","Abstract","The research in one read."],["background","B","Background","The problem and research objectives."],["methodology","M","Methodology","Six steps through the framework."],["results","R","Results","Four views of the experimental evidence."],["demonstrations","S","Slide examples","Scores, outcomes, and spatial responses."],["conclusion","✓","Conclusion","Findings, limitations, and next steps."]];
for(const [id,letter,title,copy] of guide){const a=el("a");a.href="#"+id;a.append(el("span",letter),el("h3",title),el("p",copy));$("guide").append(a);}
const steps=[
["Prepare the source-slide groups","Preserve 96 × 96-pixel patches, labels, and coordinates. Use 216 training, 54 development, and 128 labeled test groups."],
["Train three image experts","Fine-tune EfficientNetB0, MobileViT-XXS, and ResNet50 for five fixed epochs. Aggregate each image expert’s patch scores by the source-slide maximum."],
["Connect neighboring tissue patches","Combine frozen 1,280-dimensional EfficientNetB0 features with coordinates. Construct eight initial nearest neighbors, then apply residual message passing and attention pooling."],
["Stack, calibrate, and freeze","Align four expert scores, transform and standardize them, and fit logistic stacking with sigmoid calibration. Freeze the development-selected threshold at 0.628536."],
["Test each component’s contribution","Compare spatial versus self-only graphs, expert-removal variants, and shared-feature CLAM, DTFD-MIL, and CAMIL adaptations. Examine paired comparisons and three graph-head seeds."],
["Process whole slides and present outputs","Apply frozen inference to selected CAMELYON16 and supplementary SLN-Breast slides. Report WILDS separately; present scores, spatial responses, and processing records."]
];
steps.forEach(([title,copy],i)=>{const item=el("li",undefined,"card reveal"),body=el("div");body.append(el("h3",title),el("p",copy));item.append(el("span",i+1,"step-number"),body);$("steps").append(item);});
const cases=[
["True positive","positive","HobI17-313879325559",0.9013,"Reference-positive slide, correctly flagged above threshold. The manuscript describes extensive elevated ResNet50 patch responses."],
["True negative","","HobI16-553454144783",0.1806,"Reference-negative slide, correctly classified below threshold. Predominantly lower patch scores with localized elevated responses."],
["False negative","missed","HobI17-719990954481",0.2245,"Reference-positive slide, missed below threshold. Localized elevated patch responses did not produce a positive ensemble flag."]
];
for(const [label,cls,id,score,copy] of cases){const card=el("article",undefined,"case card"),scale=el("div",undefined,"score-scale"),fill=el("span");fill.style.setProperty("--score",score*100+"%");scale.setAttribute("aria-label","Score "+score+"; threshold 0.628536");scale.append(fill,el("i"));card.append(el("span",label,"badge "+cls),el("h4",id),el("strong",score.toFixed(4)),scale,el("p",copy));$("case-cards").append(card);}
const tabs=[...document.querySelectorAll('[role="tab"]')];
function activate(tab,focus=false){for(const t of tabs){const on=t===tab;t.setAttribute("aria-selected",String(on));t.tabIndex=on?0:-1;$(t.getAttribute("aria-controls")).hidden=!on;}if(focus)tab.focus();}
tabs.forEach((t,i)=>{t.addEventListener("click",()=>activate(t));t.addEventListener("keydown",e=>{let next;if(e.key==="ArrowRight")next=(i+1)%tabs.length;if(e.key==="ArrowLeft")next=(i-1+tabs.length)%tabs.length;if(e.key==="Home")next=0;if(e.key==="End")next=tabs.length-1;if(next!==undefined){e.preventDefault();activate(tabs[next],true);}});});
function openTarget(target){const parent=target.closest('[role="tabpanel"]');if(parent)activate(tabs.find(t=>t.getAttribute("aria-controls")===parent.id));for(let p=target;p;p=p.parentElement)if(p.tagName==="DETAILS")p.open=true;requestAnimationFrame(()=>target.scrollIntoView({block:"start"}));}
function followHash(){const id=decodeURIComponent(location.hash.slice(1));const target=$(id);if(target)openTarget(target);}
addEventListener("hashchange",followHash);
const menu=document.querySelector(".menu"),nav=$("links");
function closeNav(){nav.classList.remove("open");menu.setAttribute("aria-expanded","false");}
menu.addEventListener("click",()=>{const on=nav.classList.toggle("open");menu.setAttribute("aria-expanded",String(on));});
nav.addEventListener("click",closeNav);
document.addEventListener("click",e=>{if(!e.target.closest("header"))closeNav();});
document.addEventListener("keydown",e=>{if(e.key==="Escape"){closeNav();$("matches").replaceChildren();}});
const navSections=[...document.querySelectorAll("main>section[id]")],navLinks=[...nav.querySelectorAll("a")];
let ticking=false;
addEventListener("scroll",()=>{if(ticking)return;ticking=true;requestAnimationFrame(()=>{const id=navSections.filter(s=>s.getBoundingClientRect().top<innerHeight*.3).at(-1)?.id??"home";navLinks.forEach(a=>{const mapped=id==="abstract"?"overview":id==="limitations"?"conclusion":id;if(a.hash==="#"+mapped)a.setAttribute("aria-current","location");else a.removeAttribute("aria-current");});ticking=false;});},{passive:true});
function bars(target,values,max=1,precision=4){const root=el("div",undefined,"bar-chart");root.setAttribute("role","img");root.setAttribute("aria-label",values.map(([label,value])=>label+": "+Number(value).toFixed(precision)).join("; "));for(const [label,value] of values){const row=el("div",undefined,"bar-row"+(/STEGASUS|Complete ensemble/.test(label)?" featured":"")),track=el("div",undefined,"bar-track"),fill=el("div",undefined,"bar-fill");fill.style.setProperty("--value",Math.max(0,Math.min(100,Number(value)/max*100))+"%");track.append(fill);row.append(el("span",label,"bar-label"),track,el("span",Number(value).toFixed(precision),"bar-value"));root.append(row);}const axis=el("div",undefined,"bar-axis");[0,max/2,max].forEach(v=>axis.append(el("span",String(v))));root.append(axis);target.replaceChildren(root);}
function matrix(target,[tn,fp,fn,tp],unit){const t=el("table",undefined,"matrix"),cap=el("caption",unit+" · rows: reference; columns: predicted"),head=el("tr");head.append(el("th","Reference / predicted"),el("th","Negative"),el("th","Positive"));t.append(cap,head);for(const [label,pairs] of [["Negative",[[tn,"True negative","good"],[fp,"False positive",""]]],["Positive",[[fn,"False negative","miss"],[tp,"True positive","good"]]]]){const row=el("tr"),th=el("th",label);th.scope="row";row.append(th);for(const [n,kind,cls] of pairs){const cell=el("td",undefined,cls);cell.append(el("strong",n),el("span",kind));row.append(cell);}t.append(row);}target.replaceChildren(t);}
const metrics={sensitivity:["Sensitivity (%)",100,2,false],accuracy:["Accuracy (%)",100,2,false],auroc:["AUROC",1,4,false],ap:["Average precision (AP)",1,4,false],brier:["Brier score",1,4,true],logloss:["Log loss",3,4,true]};
function metricControl(select,chart,direction,models,keys){for(const key of keys){const o=el("option",metrics[key][0]);o.value=key;select.append(o);}const draw=()=>{const [label,max,precision,lower]=metrics[select.value];bars(chart,models.map(m=>[m.name,m[select.value]]),max,precision);direction.textContent=(lower?"Lower values indicate smaller probability error.":"Higher values indicate stronger performance on this measure.")+" "+label+"; bars start at zero.";};select.addEventListener("change",draw);draw();}
const cohortData={
 cam16:{title:"20 selected CAMELYON16 slides",counts:[10,0,4,6],detected:"6 / 10",finding:"Four positive slides were missed",copy:"The frozen pipeline correctly classified all ten negative slides and six positive slides. All 20 selected slides completed processing.",scope:"Balanced, reference-selected cohort with previously inspected source material. Results describe exploratory whole-slide feasibility.",auroc:"0.7200",ap:"0.8190",brier:"0.1808",logloss:"0.5278",table:11},
 sln:{title:"Ten SLN-Breast saved predictions",counts:[5,0,2,3],detected:"3 / 5",finding:"Two positive slides were missed",copy:"The analyzed subset included five positive and five negative slides. Eight predictions were correct: three positive and all five negative.",scope:"Ten of twenty selected slides had final predictions. Available-case selection and one unresolved execution-status discrepancy limit interpretation.",auroc:"0.6800",ap:"0.8111",brier:"0.2286",logloss:"0.6282",table:12}
};
function drawCohort(){const c=cohortData[$("slide-cohort").value];$("cohort-title").textContent=c.title;bars($("slide-chart"),[["Accuracy (%)",80],["Sensitivity (%)",60],["Specificity (%)",100]],100,2);matrix($("slide-matrix"),c.counts,c.title);for(const [id,value] of [["slide-detected",c.detected],["slide-finding",c.finding],["slide-interpretation",c.copy],["slide-scope",c.scope],["cohort-source","Updated manuscript, Table "+c.table]])$(id).textContent=value;$("slide-metrics").replaceChildren();for(const [label,value] of [["AUROC",c.auroc],["AP",c.ap],["Brier score",c.brier],["Log loss",c.logloss]]){const box=el("div");box.append(el("b",value),el("span",label));$("slide-metrics").append(box);}}
$("slide-cohort").addEventListener("change",drawCohort);drawCohort();
matrix($("internal-matrix"),[80,0,11,37],"128 sampled source-slide groups");
bars($("lesion-chart"),[["Micrometastasis (%)",62.96],["Macrometastasis (%)",95.24]],100,2);
function tableDetail(t){const d=el("details",undefined,"table-card");d.id="table-"+t.number;d.append(el("summary","Table "+t.number+" · "+t.title));const wrap=el("div",undefined,"scroll-table"),table=el("table",undefined,"report-table"),head=table.createTHead().insertRow();for(const name of t.columns){const th=el("th",name);th.scope="col";head.append(th);}const body=table.createTBody();for(const values of t.rows){const row=body.insertRow();values.forEach(value=>row.append(el("td",value)));}table.append(el("caption","Source: MCS-T-ADS-ASNHS-Manuscript.docx · "+t.title));wrap.append(table);d.append(wrap);return d;}
function renderArchive(data){const archive=$("archive");archive.replaceChildren();const label=el("label","Filter manuscript records"),input=el("input");input.type="search";input.placeholder="Table title, model, or dataset";label.append(input);archive.append(label);const records=[];for(const t of data.tables){const d=tableDetail(t);archive.append(d);records.push(d);}archive.append(el("p",data.figureNote,"fine"));for(const f of data.figures){const d=el("details",undefined,"figure-card");d.id="figure-"+f.number;d.append(el("summary","Supporting archive figure "+f.archiveNumber+" · "+f.caption));const img=el("img");img.loading="lazy";img.alt=f.caption;img.src=f.src;d.append(img);archive.append(d);records.push(d);}const status=el("p","","fine");status.setAttribute("role","status");archive.append(status);input.addEventListener("input",()=>{const q=input.value.trim().toLowerCase();let count=0;records.forEach(d=>{d.hidden=!d.textContent.toLowerCase().includes(q);if(!d.hidden)count++;});status.textContent=count+" matching records";});}
function renderReferences(refs){const list=$("references");for(const ref of refs){const li=el("li"),url=ref.match(/https?:\/\/\S+$/)?.[0];if(url){li.append(document.createTextNode(ref.slice(0,ref.length-url.length)));const a=el("a",url);a.href=url;a.target="_blank";a.rel="noopener";li.append(a);}else li.textContent=ref;list.append(li);}}
function renderData(data){$("abstract-text").textContent=data.abstract;renderArchive(data);renderReferences(data.references);
 const table=n=>data.tables.find(t=>t.number===n);
 const quality=Object.fromEntries(table(6).rows.map(r=>[r[0],r]));
 const expertModels=table(5).rows.map(r=>{const q=quality[r[0]];return {name:r[0],accuracy:+r[1],sensitivity:+r[2],auroc:+r[5],ap:+q[1],brier:+q[2],logloss:+q[3]};});
 metricControl($("expert-metric"),$("expert-chart"),$("expert-direction"),expertModels,Object.keys(metrics));
 const rank=Object.fromEntries(table(10).rows.map(r=>[r[0],r]));
 const mil=table(9).rows.map(r=>{const q=rank[r[0]];return {name:r[0],accuracy:+r[1],sensitivity:+r[2],auroc:+q[1],ap:+q[2],brier:+q[3],logloss:+q[4]};});
 metricControl($("mil-metric"),$("mil-chart"),$("mil-direction"),mil,["sensitivity","auroc","ap","brier","logloss"]);
 bars($("spatial-chart"),table(7).rows.map(r=>[r[0],+r[2]]),1,5);
 bars($("ablation-chart"),table(8).rows.map(r=>[r[0],+r[2]]),100,2);
 followHash();
}
fetch("data/manuscript.json?v=20261127").then(r=>{if(!r.ok)throw Error("Manuscript unavailable");return r.json();}).then(renderData).catch(()=>{$("archive").textContent="The evidence archive could not be loaded. Reload the page to retry.";$("abstract-text").textContent="STEGASUS combines three image classifiers, a Spatial Graph Expert, and calibrated logistic stacking for exploratory breast cancer lymph-node metastasis research. The full manuscript abstract could not be loaded.";$("expert-chart").textContent="Comparison data could not be loaded. Reload to retry.";$("mil-chart").textContent="Comparison data could not be loaded.";});
function search(term){const q=term.trim().toLowerCase(),box=$("matches");box.replaceChildren();if(!q)return;const terms=q.split(/\s+/);const sections=[...document.querySelectorAll("main>section, [role=tabpanel], #archive details")];const found=sections.filter(n=>terms.every(t=>n.textContent.toLowerCase().includes(t))).filter(n=>!n.querySelector('[role=tabpanel]')).slice(0,8);if(!found.length){box.textContent="No matching research sections or records.";return;}for(const target of found){const label=target.querySelector("summary,h2,h3")?.textContent??"Study record",a=el("a",label);a.href="#"+target.id;a.addEventListener("click",()=>{openTarget(target);box.replaceChildren();});box.append(a);}}
$("search").addEventListener("submit",e=>{e.preventDefault();search($("query").value);});
document.querySelectorAll(".chips button").forEach(b=>b.addEventListener("click",()=>{$("query").value=b.textContent;search(b.textContent);}));
if("IntersectionObserver" in window&&!matchMedia("(prefers-reduced-motion: reduce)").matches){const io=new IntersectionObserver(entries=>{for(const entry of entries)if(entry.isIntersecting){entry.target.classList.add("is-visible");io.unobserve(entry.target);}},{threshold:.12});document.querySelectorAll(".reveal").forEach(n=>io.observe(n));}

